(
    float4 iPosition : POSITION,
    float3 iNormal : NORMAL,
    float4 iTexCoord0 : TEXCOORD0,
    float4 iColor : COLOR0,

    out float4 oPosition : POSITION,
    out float4 oTexCoord0 : TEXCOORD0,
